CREATE TABLE IF NOT EXISTS subscriptions (id serial PRIMARY KEY, profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, merchant text NOT NULL, amount numeric(18,2) NOT NULL, frequency text NOT NULL DEFAULT 'monthly', next_charge_date text, status text NOT NULL DEFAULT 'active', cancel_url text, source text NOT NULL DEFAULT 'detected', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS subscriptions_profile_status_idx ON subscriptions(profile_id,status);
CREATE TABLE IF NOT EXISTS receipts (id serial PRIMARY KEY, profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, transaction_id integer REFERENCES transactions(id) ON DELETE SET NULL, filename text NOT NULL, storage_key text, merchant text, amount numeric(18,2), purchased_at text, ocr_status text NOT NULL DEFAULT 'manual_review', extracted_data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tax_tags (id serial PRIMARY KEY, profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, transaction_id integer NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, tax_year integer NOT NULL, classification text NOT NULL, deductible_percent numeric(5,2) NOT NULL DEFAULT 100, note text, UNIQUE(profile_id,transaction_id));
CREATE TABLE IF NOT EXISTS monthly_reviews (id serial PRIMARY KEY, profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, month text NOT NULL, step integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'in_progress', answers jsonb NOT NULL DEFAULT '{}'::jsonb, completed_at timestamptz, UNIQUE(profile_id,month));
CREATE TABLE IF NOT EXISTS notification_preferences (id serial PRIMARY KEY, profile_id integer NOT NULL UNIQUE REFERENCES profiles(id) ON DELETE CASCADE, low_balance boolean NOT NULL DEFAULT true, bills boolean NOT NULL DEFAULT true, budgets boolean NOT NULL DEFAULT true, subscriptions boolean NOT NULL DEFAULT true, weekly_digest boolean NOT NULL DEFAULT true, low_balance_threshold numeric(18,2) NOT NULL DEFAULT 500);
CREATE TABLE IF NOT EXISTS notifications (id serial PRIMARY KEY, profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, type text NOT NULL, title text NOT NULL, message text NOT NULL, action_url text, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_profile_read_idx ON notifications(profile_id,read_at);
CREATE TABLE IF NOT EXISTS credit_snapshots (id serial PRIMARY KEY, profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, score integer, utilization numeric(5,2), total_limit numeric(18,2), statement_balance numeric(18,2), source text NOT NULL DEFAULT 'manual', snapshot_date text NOT NULL, UNIQUE(profile_id,snapshot_date));
CREATE TABLE IF NOT EXISTS investments (id serial PRIMARY KEY, profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, account_id integer REFERENCES accounts(id) ON DELETE SET NULL, symbol text NOT NULL, name text NOT NULL, asset_class text NOT NULL, quantity numeric(24,8) NOT NULL, cost_basis numeric(18,2) NOT NULL DEFAULT 0, current_price numeric(18,4) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dashboard_layouts (id serial PRIMARY KEY, profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, name text NOT NULL, widgets jsonb NOT NULL DEFAULT '[]'::jsonb, is_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(profile_id,name));
CREATE TABLE IF NOT EXISTS household_approvals (id serial PRIMARY KEY, household_id integer NOT NULL REFERENCES households(id) ON DELETE CASCADE, requested_by_profile_id integer NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, type text NOT NULL, title text NOT NULL, amount numeric(18,2), payload jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'pending', decided_by_profile_id integer REFERENCES profiles(id) ON DELETE SET NULL, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
